

import typing

import pydantic
import typing_extensions
from ..core.pydantic_utilities import IS_PYDANTIC_V2, UniversalBaseModel
from ..core.serialization import FieldMetadata
from .part_input import PartInput


class ArtifactInput(UniversalBaseModel):
    """
    Represents a file, data structure, or other resource generated by an agent during a task.
    """

    artifact_id: typing_extensions.Annotated[str, FieldMetadata(alias="artifactId"), pydantic.Field(alias="artifactId")]
    description: typing.Optional[str] = None
    extensions: typing.Optional[typing.List[str]] = None
    metadata: typing.Optional[typing.Dict[str, typing.Any]] = None
    name: typing.Optional[str] = None
    parts: typing.List[PartInput]

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
